window.VD=window.VD||{};window.VD["vw/passat-b6"]={"passat-b6-activate-turn-signals-in-us-mode":"<p><strong>Purpose:</strong> to activate US indicators. (Passat B6 only)   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>Byte 7</strong>: Set value<strong> 32</strong> in <strong>Dec</strong> box (value in % of intensity, origin: 0)</p>\n<p>Decimal examples shown in yellow in the image:<br/>14 (corresponds to a 20% variation in the indicator lights)<br/>1E (corresponds to a 30% variation in the indicator lights)<br/>28 (corresponds to a 40% variation in the indicator lights)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3C0-937-049-Q_Module09_Byte7-16502f21.webp\"/></figure>","passat-b6-adjust-light-sensor-sensitivity":"<p><strong>Purpose: </strong>Adjusts the sensitivity of the light sensor.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>2</strong>: </em><br/> Bits<em><strong> 0-7</strong></em> (187, 205 or 237 to increase sensitivity, or 45, 40 or 33 to decrease sensitivity)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/lightsensorg5-1e88d9a5.webp\"/></figure>","passat-b6-ambient-light-intensity":"<p><strong>Purpose:</strong> Used to adjust ambient lighting intensity.  </p>\n<p><strong>Procedure</strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation 10</strong>”.</p>\n<p><strong>5</strong> – Select <strong>Channel 05</strong> (Footwell Lightning Dimming)  </p>\n<p><strong>6 –</strong> Select intensity from 20 to 100% (in 1% increments)</p>","passat-b6-automatic-door-locking":"<p><strong>Purpose: </strong>to set automatic door locking from 15km/h.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Comfort Module.”</strong><br/><br/><strong>4 – </strong>Click “ <strong>Adaptation – 10”</strong> </p>\n<p><strong>Channel 04</strong></p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres_vw-auto-loc-ce03b1da.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Auto-Lock (Automatic Locking above 15 km/h)”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","passat-b6-automatic-door-unlocking":"<p><strong>Purpose: </strong>to configure automatic door unlocking when the ignition key is removed.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Comfort Module.”</strong><br/><br/><strong>4 – </strong>Click “ <strong>Adaptation – 10”</strong> </p>\n<p><strong>Canal 05</strong></p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw-door-unlock-798a1163.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong><em>If the adaptation channel is not activated.</em></strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>3</strong>: Check “Auto-Unlock (Unlocking when Removing the Ignition Key)”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","passat-b6-change-odb-language":"<p><strong>Purpose </strong>: To change the language of the ODB. (Highline MFA)  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 04</strong></p>\n<p><em>Set the value according to the selected language</em></p>\n<p><em>1 = German</em><br/><em>2 = English</em><br/><em>3 = French</em><br/><em>4 = Italian</em><br/><em>5 = Spanish</em><br/><em>6 = Portuguese</em></p>","passat-b6-coming-home-time-setting":"<p><strong>Purpose:</strong> Set the length of time the headlights remain on after the car is locked.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong> </p>\n<p><strong>5</strong> – Select <strong>Channel 01</strong> (Coming-Home Time)  </p>\n<p><strong>6</strong> – Select duration from <strong>0 to 60 sec</strong> (in 1sec increments).</p>","passat-b6-corner-lights-activation":"<p><strong>Purpose</strong>: to activate cornering lights with fog lamps.  </p>\n<p><strong>Modification only possible for vehicles with a 30 Byte power plant</strong> </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>23</strong>: </em><br/><em>Bit <strong>2</strong>: Check “Internal Turn Light Control Algorithm active”.</em><br/><em>Bit <strong>3-4</strong>: Select “08 Turn Lights via fog lights” from the drop-down list</em></p>","passat-b6-correction-of-odb-consumption-display":"<p><strong>Purpose</strong>: to correct the fuel consumption display on the on-board computer.  </p>\n<p><strong>Modification only possible on Mid/High range models</strong>. <br/><em>Note: modifications affect the display of instantaneous consumption, average consumption and fuel quantity.</em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on <strong>“17 – Instruments”</strong>. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation- 10</strong>”.</p>\n<p><strong>5</strong> – Select <strong>Channel 03</strong> <em>“Consumption Correction”.</em></p>\n<p><em>Adjust consumption correction factor between 85% and 115%.</em> <em>(base value: 100)</em></p>\n<p><em>Example 1: Calculation based on volume per distance (e.g. l/100 km): DIS: 9.3 l/100 km. Actual: 9.8 l/100 km. (100, 9,8 / 9,73 ? 105,38) Channel 3 will be changed from 100 to 105 <br/>Example 2: Calculation based on volume distance (e.g. MPG is: DIS: 23 MPG. Actual: 24 MPG. (100, 23/24 and 95.83) Channel 3 will be changed from 100 to 96</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/correction-consommation-odb-d51db18e.webp\"/></figure>","passat-b6-cruise-control-activation-retrofit":"<p><strong>Purpose:</strong> to activate the speed governor after retrofitting.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>01 – Motor</strong> “.</p>\n<p><strong>4</strong> – Click on ” <strong><strong>Access</strong></strong> – <strong> 11</strong> ” then enter the code ” <strong><em><strong>11463</strong></em></strong> ” </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur2-6871f13e.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>16 – Steering Wheel</strong>“.</p>\n<p><strong>4</strong> – Click on ” <strong>Coding – 07</strong> ” then </p>\n<p><em>The penultimate digit (0xxxx<strong>?</strong>x) is used to configure the cruise control.</em><br/><em>Enter <strong>2</strong> if you don’t have an on-board computer</em><br/><em>Set <strong>4</strong> if you have an on-board computer</em></p>\n<p>.</p>","passat-b6-deactivate-brake-pad-warning-light":"<p><strong>Purpose: </strong> Allows you to disable the brake pad wear warning light on the OBD (On-Board Diagnostics) system, for example, for brake pads without a sensor or if the sensor is malfunctioning / Brake Pad Warning Light Deactivation. </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>17 – Instruments</strong>.”<br/><br/><strong>4 – </strong>Click on <strong>“Coding –</strong> 07”  </p>\n<p><em>The first two digits of the code (<strong>??</strong>xxxx) are used to modify the Instrument module options. To remove the brake pad indicator, subtract <strong>01</strong> from these digits. </em><br/><em>Example of initial coding: <strong>03142</strong></em><br/><em>To turn off the brake pad warning light, simply recode it as follows: <strong>02142</strong> (03 – 01 = 02)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-920-820-E_Module17_Coding-de79aff6.webp\"/></figure>\n<p>To activate the brake pad indicator: +01</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant-frein-d4619ec9.gif\"/></figure>","passat-b6-deactivate-windshield-washer-indicator":"<p><strong>Purpose </strong>: to deactivate the windshield washer indicator on the ODB (on-board computer).  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p><em>The first two digits of the code (<strong>??</strong>xxxx) are used to modify the Instrument module options. To remove the ice-washer indicator, subtract <strong>04</strong> from these digits. </em><br/><em>Example of initial coding (with washer indicator): <strong>05142</strong></em><br/><em>To remove the windscreen washer indicator, simply recode as follows: <strong>01142</strong> (05 – 04 = 01)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-920-820-E_Module17_Coding-de79aff6.webp\"/></figure>\n<p>To activate the ice washer indicator: +04</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglace-edc83d4f.webp\"/></figure>","passat-b6-deactivate-activate-electric-handbrake-for-rear-brake-pad-change":"<p><strong>Purpose:</strong> to deactivate/activate the electric handbrake in maintenance mode in order to change/replace the rear brake pad/disc linings. (EPB reset / Lining change mode)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/>To start, set the gear lever to P, remove the electric handbrake on the button and preferably connect a battery charger according to the vehicle manual. Check that there are no faults/errors before starting basic setup.<br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“53 – Parking Brake</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Basic setting</strong> <strong>– 04</strong>”.<br/><br/><strong>5</strong> – Select Channel <strong>007</strong><br/><br/><strong>6</strong> – Click on<strong>“Go</strong>”.</p>\n<p>Basic Settings: <strong>OFF</strong> during the procedure, then <strong>ON</strong> when finished (yellow arrow).</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/53epb007-8e9a2db6.webp\"/></figure>\n<p>A fault message will appear on your ODB indicating<strong>“Parking brake fault</strong>” and an LED in the parking brake switch, but this is normal and should be ignored.<br/><br/> 7 – Once finished, go back (Done, Go Back) until the program closes.<br/><br/> 8 – Switch off the vehicle’s ignition, then disconnect the VAG-COM cable<br/><br/> 9 – <strong>Change the linings on both sides!</strong><br/><br/><br/></p>\n<p><strong>To reactivate the electric handbrake :</strong><br/><br/><br/><strong>10</strong> – With engine off and ignition switched off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>11</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>12</strong> – Click on<strong>“Select”</strong> then click on<strong>“53 – Parking Brake</strong>”.<br/><br/><strong>13</strong> – Click on<strong>“Basic setting – 04</strong>”.<br/><br/><strong>14</strong> – Select Channel <strong>006</strong><br/><br/><strong>15</strong> – Click on<strong>“Go</strong>”.<br/><br/>Basic Settings: <strong>OFF</strong> during the procedure, then <strong>ON </strong>when finished (yellow arrow).</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/53epb006-52154901.webp\"/></figure>\n<p><strong>16</strong> – Once finished, go back (Done, Go Back) until the program is closed.</p>\n<p><strong>17</strong> – Switch off the ignition and disconnect the VAG-COM cable.</p>","passat-b6-defrost-time-setting":"<p><strong>Purpose:</strong> to set the operating time for mirror and rear window defrosting.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong> then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 03</strong> (Rear Window &amp; Outside Mirror Heater Activation Time)  </p>\n<p><strong>6</strong> – Select duration from <strong>1 to 254 min</strong> (in 1 min increments).</p>","passat-b6-delete-belt-alarm":"<p><strong>Purpose</strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> –  <em>The third and fourth coding digits (xx<strong>??</strong>x0x) are used to modify Instrument module options. To suppress the belt alarm, subtract <strong>2</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial coding (with belt alarm) is: <strong>0023103</strong></p>\n<p>To delete the belt alarm, simply recode as follows: <strong>0021103 </strong><em>(23 – 02 = 21)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","passat-b6-display-speed-on-rcd-300":"<p><strong>Purpose:</strong> To add a driving-school mode view to the RCD 300 that displays speed (also ideal for accompanied driving) <br/><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“56 – Radio</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Channel 2</strong>” “Driving School Function”.<br/><br/><strong>7</strong> – Set value to <strong>1</strong>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RCD300_Module56_Channel02-3c0994f0.webp\"/></figure>\n<p>To activate the function:<br/>– Switch off the RCD-300<br/>– Press the MENU button<br/>– Keep the MENU button pressed and switch on the RCD-300.</p>\n<p><em>(To return to normal display, execute the same sequence)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_rcd300-efa2d2ba.webp\"/></figure>","passat-b6-donut-style-taillights":"<p><strong>Purpose:</strong> Enables the Donut/Skyline-style taillights.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/donut-5babb7d4.webp\"/></figure>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>Byte 9</strong>: Set value<strong> 00</strong> in <strong>Dec</strong> box (origin: 40)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7644-1024x409-95f3c123.webp\"/></figure>","passat-b6-door-lock-confirmation-key":"<p><strong>Purpose: </strong> Allows you to configure the door lock confirmation when using the key.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.<br/><br/><strong>4 – </strong> Click “<strong>Adaptation – 10</strong>“</p>\n<p><strong>Channel 11</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<p><strong>Line 2: </strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>11</strong>: </em><br/><em>Bit <strong>0: </strong> Check “Locking Confirmation (Blink) via Door Locks” (confirmation with blinking lights)</em><br/><em>Bit <strong>1</strong>: Check “Locking Confirmation (Horn) via Door Locks” (confirmation with a beep or horn)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/locking_196-096e4b1a.webp\"/></figure>","passat-b6-door-lock-confirmation-remote-control":"<p><strong>Purpose: </strong> Allows you to configure the door lock confirmation when using the remote control. </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 10</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vagcom-golf5-e5c80be6.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>11</strong>: </em><br/><em>Bit <strong>2: </strong> Check “Locking Confirmation (Blink) via Remote Control” (confirmation with turn signals)</em><br/><em>Bit <strong>3</strong>: Check “Locking Confirmation (Horn) via Remote Control” (confirmation with a beep or horn)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/locking_196-096e4b1a.webp\"/></figure>","passat-b6-door-lock-unlock-confirmation-beep":"<p><strong>Purpose: </strong>Enables vehicle lock/unlock confirmation with beeps (with alarm)  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“46 – Central Conv.</strong></p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><strong>6 </strong>– Select <em>Byte <strong>10</strong>: </em><br/><em>Bit <strong>1</strong>: Check “Unlocking Confirmation (Horn) via Door Locks”</em><br/><em>Bit <strong>3</strong>: Check “Unlocking Confirmation (Horn) via Remote Control </em>”.  </p>\n<p>Then<em>byte <strong>11</strong>: </em><br/><em>Bit <strong>1</strong>: Check “Locking Confirmation (Horn) via Door Locks”</em><br/><em>Bit <strong>3</strong>: Check “Locking Confirmation (Horn) via Remote Control </em>”.  </p>","passat-b6-door-unlock-confirmation-remote-control":"<p><strong>Purpose </strong>: to set the door unlock confirmation when using the remote control.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 07</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>10</strong>: </em><br/><em>Bit<strong> 2</strong>: Check “Unlocking Confirmation (Blink) via Remote Control” (confirmation with flashing lights)</em><br/><em>Bit <strong>3</strong>: Tick “Unlocking Confirmation (Horn) via Remote Control” (confirmation with Beep/Horn)</em></p>","passat-b6-door-unlocking-confirmation-key":"<p><strong>Purpose: </strong> Allows you to configure the door unlock confirmation when using the key.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 08</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>10</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Unlocking Confirmation (Blink) via Door Locks” (confirmation with blinking lights)</em><br/><em>Bit <strong>1</strong>: Check “Unlocking Confirmation (Horn) via Door Locks” (confirmation with a beep or horn)</em></p>","passat-b6-easy-entry":"<p><strong>Purpose </strong>: automatically moves the power seat back and straightens the backrest when the ignition is switched off and the door opened.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>36 – Driver’s Seat</strong>” . 2 – Switch on the ignition and run the VCDS program. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4 </strong>– Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select Channel <strong>60</strong> (Easy Entry) :</p>\n<p><em>Set value to </em><strong><em>“1</em></strong>”</p>","passat-b6-flash-mode-lights-during-emergency-braking":"<p><strong>Purpose</strong>: activates brake lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>17</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Emergency Brake Flash Light active”.</em></p>","passat-b6-headlight-washer-duration-setting":"<p><strong>Purpose:</strong> Allows you to set how long the headlight washers remain activated.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong> </p>\n<p><strong>5</strong> – Select <strong>Channel 04</strong> (Headlight Washer Activation Time)  </p>\n<p><strong>6</strong> – Select a duration between <strong>50 and 10,000 ms</strong> (in 50-ms increments).</p>","passat-b6-leaving-home-duration-setting":"<p><strong>Purpose:</strong> to set the length of time the headlights remain on after the car is unlocked.  </p>\n<p><strong>Procedure: </strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong> </p>\n<p><strong>5</strong> – Select <strong>Channel 02</strong> (Leaving-Home Time)  </p>\n<p><strong>6</strong> – Select duration from <strong>0 to 60 sec</strong> (in 1sec increments).</p>","passat-b6-modifying-power-steering-hardness":"<p><strong>Purpose </strong>: to adjust the hardness of the power steering for a softer or harder steering wheel.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“44 – Direction assistée” / “44-steering assist.</strong><br/><br/><strong>4 </strong>– Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5 – </strong>Select<strong> Channel 1 </strong>, <em>set a value between<strong> 1</strong> and <strong>15</strong> depending on your hardness preference</em>.</p>\n<p><strong>Or Line 2: (If channel 1 is unavailable)</strong>:<br/><br/> 3 – Click on<strong>“Select</strong>” then click on<strong>“44 – Direction assistée” / “44-steering assist.”</strong><br/><br/> 4<strong>– </strong> Click on<strong>“Coding – 07</strong>”.</p>\n<p><strong>5 – </strong>Select :</p>\n<ul>\n<li>xxx1x for smooth steering</li>\n<li>xxx2x for sports management</li>\n<li>xxx3x for hard steering</li>\n<li>xxx4x for harder steering</li>\n<li>xxx5x for very hard steering</li>\n</ul>","passat-b6-one-touch-window-closure":"<p><strong>Purpose</strong>: to activate closing and opening of the windows and sunroof with the remote control <strong>WITHOUT </strong>remaining pressed until the windows are completely closed.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition turned off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition and launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Central Conv.”</strong></p>\n<p><strong>4</strong> – Click ” <strong>Encoding 07</strong>,” then “Long Coding Helper”</p>\n<p><strong>5 –</strong> <em>Byte <strong>6</strong>: </em><br/><em>Bit <strong>6</strong>: Check “Comfort Function automatic Closing”.</em></p>\n<ul>\n<li>Uncheck “Comfort function power windows/sunroof via remote control inactive”.</li>\n<li>Check “Comfort opening power windows via remote control active”.</li>\n<li>Check “Comfort closing power windows via remote control active”.</li>\n<li>Check “Closing sunroof via remote control active” (sunroof)</li>\n</ul>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/ComfortConv-byte6-9f2c129f.webp\"/></figure>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Comfort Module.”</strong><br/><br/><strong>4 – </strong>Click “ <strong>Adaptation – 10”</strong> </p>\n<p><strong>Channel 17</strong> (Comfort function)</p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_0944-1024x741-ec4d5180.webp\"/></figure>\n<p><em>Pressing the remote control’s close button for 3 seconds will first lock the doors and then close the windows, without having to keep the button pressed until they are fully closed</em>.</p>","passat-b6-programming-a-remote-control":"<p><strong>Purpose:</strong> Allows you to program the remote controls that will be used with the vehicle for central locking and unlocking.  </p>\n<p>⚠️ <strong>WARNING:</strong> This procedure does not allow you to program the remote controls with the vehicle’s immobilizer.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 01 ( </strong>“Remote Control Adaptation” from the drop-down list)</p>\n<p>Enter the number of keys to program, then click <strong>Save</strong>.<br/>Next, press the <strong>Unlock</strong> button on each remote control to be programmed for at least 1 second. The flashing lights will confirm the procedure.<br/>All keys must be programmed in a single session, one after the other.<br/>Programming all keys must not take longer than <strong>15 seconds</strong>.<br/>You can add up to <strong>4 remote controls</strong>. If the <strong>[Test]</strong> and/or <strong>[Save]</strong> buttons are grayed out and unclickable, the module likely has all 4 slots filled; delete the remote controls using the <strong> “Reset Remote Controls”</strong> tutorial.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel01-10148edb.webp\"/></figure>","passat-b6-resetting-the-remote-controls":"<p><strong>Purpose:</strong> Resets the settings for all remote controls associated with the vehicle.</p>\n<p><strong>⚠️ WARNING:</strong> After completing this procedure, all remote controls will be deleted and will need to be reprogrammed using the <strong>“How to Program a Remote Control”</strong> tutorial <strong>.</strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 00</strong></p>\n<p><em>Set the value to <strong>0</strong> and save</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel00-caced031.webp\"/></figure>","passat-b6-selective-door-unlocking":"<p><strong>Purpose </strong>: Used to set up selective door unlocking. </p>\n<p>When unlocking the vehicle, only the driver’s door is unlocked. To unlock all doors, press the remote control’s unlock button twice.   </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 03</strong></p>\n<p><em>Set value to 1</em></p>\n<p><strong>Line 2:</strong></p>\n<p><strong><em>If the adaptation channel is not activated.</em></strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>0</strong>: Check </em><em>“Selective Central Locking (Single Door Opening)</em>”.<em> </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres-1K0_Module4-be0b33ff.webp\"/></figure>","passat-b6-show-hidden-menu-climatronic":"<p><strong>Purpose: </strong>to display the Climatronic’s hidden menu.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/menu-cache-climatronic-golf5-7154b4a2.webp\"/></figure>\n<p><strong>Displaying instantaneous digital speed? it’s possible! </strong>  No need to use your VCDS VAG-COM cable for this tutorial.</p>\n<p><strong>Proceed :</strong></p>\n<p>It’s really quite simple. <strong>Just press the “ECON” button on your air conditioner and the “air extraction up” button, symbolized by a person with an arrow pointing upwards, at the same time</strong>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatronic1-5edb6af4.gif\"/></figure>\n<p>Then simply move the driver-side climate control knob to access the various temperatures and functions.</p>\n<p><strong>What’s it for?</strong></p>\n<p>The main things to check are engine temperature, cabin temperature, exterior temperature and digital speed.</p>\n<p>For digital speed:  </p>\n<p>Then set to -19.0 in the left-hand display by turning the left-hand knob, and the right-hand display gives you the “real” speed in km/h.</p>\n<p>This is because the “real” speedometer is different from the analogue speedometer (needle) which has passed 60km/h.</p>\n<p>Above 99km/h, the right display alternates between the 100km/h in the small right-hand corner and the remaining two digits in the large right-hand corner.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatronic2-1d05bbc0.gif\"/></figure>\n<p>Turning the central knob changes the small exponent number on the left display, which changes the display on the right to a small 2 – the speed is in mph.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/climatronic3-04295505.gif\"/></figure>\n<hr/>\n<p><strong>List of hidden Climatronic functions</strong></p>\n<p><br/>The beginning of each paragraph symbolizes a function (1st line) followed by sub-functions (following lines).</p>\n<p><strong>0</strong> System data (temperature setting left)<br/>0 Program number Dig. (temperature setting right)<br/>1 ERL disaster Dig.<br/>2 ERL right Dig.<br/>3 Working point on/on Dig.<br/>4 Automatic ricircolo (motor)/Automatic ricircolo Bit Dig.<br/>5 Heating as stopped I activate Dig.<br/>6 Air quality<br/>7 Derivative Dig.<br/>8 Country code Dig.<br/>9 Zone sensor test °C </p>\n<p><strong>1</strong> UIF (temperature setting left)<br/>0 Internal temperature °C (temperature setting right)<br/>1 Surface temperature °C<br/>2 Platinum piastrin temperature (?) °C<br/>3 Platinum piastrin corrector (?) °C<br/>4 uif-Sonnenint (?) Dig.<br/>5 Radiation corrector (?) °C<br/>6 Dynamic correctors °C<br/>7 Ricircolo corrector °C<br/>8 Thermal correctors °C<br/>9 UIF ignition compensation °C</p>\n<p><strong>2</strong> Irradiance sensor SX<br/>0 Irradiance not delayed (?) W/m2<br/>1 Irradiance corrector for temperature controller W/m2<br/>2 Irradiance corrector for fan W/m2<br/>3 Value to be digitized.</p>\n<p><strong>3</strong> Irradiance sensor DX<br/>0 Irradiance not delayed (?) W/m2<br/>1 Irradiance correction for temperature controller W/m2<br/>2 Irradiance correction for fan W/m2<br/>3 Value to be digitized.</p>\n<p><strong>4</strong> Outdoor temperature<br/>0 Outdoor temperature °C<br/>1 Temp. Outdoor CAN line °C<br/>2 Intake air temperature climate °C </p>\n<p><strong>5</strong> Theoretical SX temperature<br/>0 Theoretical SX outlet air temp. °C<br/>1 Difference between theoretical and actual temp. °C<br/>2 Value of sx. regulation ½ % /Dig<br/>3 Stell-Max (?) ½ % /Dig<br/>4 Defrost SX    </p>\n<p><strong>6</strong> Noticed temperature SX<br/>0 Temp. Noticed SX °C<br/>1 Temp. Feet SX °C<br/>2 Temp. Frontal SX °C   </p>\n<p><strong>7</strong> Theoretical temperature DX<br/>0 Theoretical air temperature DX °C<br/>1 Difference between theoretical and actual temperature DX °C<br/>2 Control values controller ½ % /Dig<br/>3 Stell-Max (?) ½ % /Dig<br/>4 Defrost DX   </p>\n<p><strong>8</strong> Noticed temperature DX<br/>0 Noticed outlet air temp. DX °C<br/>1 Temp. Feet °C<br/>2 Temp. Frontal °C   </p>\n<p><strong>9</strong> Theoretical evaporator temperature<br/>0 Theoretical evaporator temperature °C<br/>1 Difference between theoretical and effective evaporator temp. °C<br/>2 Evaporator control values 5mA/Dig<br/>3 Evaporator control modes (see below)  </p>\n<p><strong>10</strong> Effective evaporator temperature<br/>0 Effective evaporator temperature °C<br/>1 Refrigerant pressure climate bar<br/>2 Average refrigerant temperature climate °C</p>\n<p><strong>11</strong> Compressore clim<br/>0 Theoretical electric power but<br/>1 Effective electric power but<br/>2 Max electric power but<br/>3 Kompressor PWM (0… 200) Dig<br/>4 Electric power compressore offset<br/>5 Electric power values<br/>6 Code compressore disinserito</p>\n<p><strong>12</strong> Fan climate<br/>0 Theoretical fan voltage V<br/>1 Manual control<br/>2 Fault code<br/>3 Riduction fan V<br/>4 Offset fan (from here to automatic mode) 0.1V</p>\n<p><strong>13</strong> Bocchette air temperature SX<br/>0 Theoretical value formattato %<br/>1 Theoretical value actual temp. Bocchette sx. Dig.<br/>2 Conferma el. temp. Bocchette sx. Dig.<br/>3 Limite plus grand temp. Bocchette sx. Dig.<br/>4 Limit min. temp. Bocchette sx. Dig.          </p>\n<p><strong>14</strong> Bocchette air temperature DX<br/>0 Theoretical value formattato %<br/>1 Theoretical value real temp. Bocchette dx Dig.<br/>2 Conferma el. temp. Bocchette dx Dig.<br/>3 Limite plus grand temp. Bocchette dx. Dig.<br/>4 Limit min. temp. Bocchette dx. Dig.        </p>\n<p><strong>15</strong> Temperature bocchetta pieds/centrale<br/>0 Theoretical value formattato %<br/>1 Actual theoretical value temp. Bocchetta centrale Dig.<br/>2 Conferma el. temp. bocchetta centrale Dig.<br/>3 Limite plus grand temp. bocchetta centrale Dig.<br/>4 Limite min. temp. bocchetta centrale Dig.      </p>\n<p><strong>16</strong> Pelle Defrost<br/>0 Theoretical value formattato %<br/>1 Actual theoretical value pelle Defrost Dig.<br/>2 Conferma el. pelle Defrost Dig.<br/>3 Limit plus pelle Defrost Dig.<br/>4 Limit min. pelle Defrost Dig.  </p>\n<p><strong>17</strong> Pelle ricircolo interne<br/>0 Valeur théorique formattato %<br/>1 Valeur théorique réelle pelle ricircolo Dig.<br/>2 Conferma el. pelle ricircolo Dig.<br/>3 Limite plus grand pelle ricircolo Dig.<br/>4 Limite min. pelle ricircolo Dig.  </p>\n<p><strong>18</strong> Cold air shovel<br/>0 Theoretical value formattato %<br/>1 Theoretical actual value Cold air shovel Dig.<br/>2 Conferma el. Pelle air froid Dig.<br/>3 Limite plus grand Pelle air froid Dig.<br/>4 Limite min. Cold air shovel Dig.  </p>\n<p><strong>19</strong> Motor data<br/>0 Speeds’ km/h<br/>1 Motor temperature °C<br/>2 Motor rpm U/min<br/>3 Compressor rpm climate U/min</p>\n<p><strong>20</strong> Data sent on CAN<br/>0 of Additional heating (on demand)1 = inserted<br/>1 Conferma el. PTC 1 = inserted<br/>2 Puissance el. effective PTC à 3% air demandé radiatore de<br/>clima%<br/>4 Rappo% de pic de l’air radiatore%<br/>5 Aucune prestation demandée au disp. de chauffage 1=nessuna prestation chauffage   </p>\n<p><strong>21</strong> Ripartitore d’air Climat<br/>0 Defrost% 1 Frontale%<br/>2 Piedi%<br/>3 Bocchetta areazione%<br/>4 Ricircolo air frais/propre (+ bocchetta… ?) %<br/>5 Évaluation sensore%</p>\n<p><strong>22</strong> Timer data<br/>0 Stop period min.<br/>1 Motor running time S<br/>2 Running time with key inserted s</p>\n<p><strong>23</strong> Special channel<br/>0 Internal lighting sensor Dig.<br/>1 Air quality sensor</p>\n<p><strong>24</strong> Software version<br/>0 Development status<br/>1 Software version<br/>2 Type SW<br/>3 Keep Frozen<br/>4 Version K Matrix<br/>5 EEP -Testflags<br/>6 Codifica Vag (?) 2</p>\n<p><strong>25</strong> Canali di prova<br/>0 Canale 0<br/>1 Canale1<br/>2 Canale2<br/>3 Canale3<br/>4 Canale4<br/>5 Canale5<br/>6 Canale6<br/>7 Canale7<br/>8 Canale8<br/>9 Canale9</p>\n<p><strong>26</strong> Parameters for readings on crystals<br/>0 I delay s<br/>1 Step/udm (?) digit<br/>2 Limit minimo digit<br/>3 Limit max. digit<br/>4 Step/udm on HellaKit (?) 1=ein </p>\n<p><strong>27</strong> Bocchetta areazione directe<br/>0 Theoretical value formattato%<br/>1 Actual theoretical value Bocchetta areazione directe Dig.<br/>2 Conferma el. Bocchetta areazione directe Dig.<br/>3 Limite max. Bocchetta areazione directe Dig.<br/>4 Limite min. Bocchetta areazione directe Dig.   </p>\n<p><strong>28</strong> Umidita<br/>0 Umidita’22#teorica%<br/>1 Umidita’relative to temperature UIF ? %<br/>2 Temp. WSS crystals °C<br/>3 Temperature of condensation °C<br/>4 Melting point temperature difference °C </p>\n<p><strong>29</strong> Raw values himidity<br/>0 Temp. Crystals, corrected °C<br/>1 Temp.  Crystals, uncorrected °C<br/>2 Sensor umidità%<br/>3 Sensor temperature °C<br/>4 Condensation point temperature (test measurement) °C<br/>5 Fault code</p>\n<p><strong>30</strong> Indicated values you himidity<br/>0 Sensor value termofil oDig.<br/>1 Temperatura rif. termofilo Dig.<br/>2 Periodic duration himidity 10-4 sec<br/>3 Temp. Reference himidity Dig.<br/>4 Himidity Rel. on sensore%<br/>5 Sensor temperature himidity °C<br/>6 Crystal temperature (uncorrected) °C   </p>\n<p><strong>What’s in it for me?</strong></p>\n<p>None, unless you like numbers, and the fact that you can see your speed in real time other than with a needle is very nice.</p>\n<p><strong>How do I get out of this menu?</strong></p>\n<p>By switching off the engine or pressing the “AUTO” and “ECON” buttons simultaneously.</p>","passat-b6-activate-daytime-running-lights-with-fog-lamps-drl":"<p><strong>Purpose</strong>: Allows fog lights to be used as daytime running lights.  </p>\n<p><strong>Procedure</strong>: <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.<br/><br/><strong>2</strong> – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>6 –</strong> <em>Byte 0: </em><br/><em>Bit 4: Check “Daytime Running Lights (North America)”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/scandinavie_194-c7df4fa8.webp\"/></figure>\n<p><strong>7 – </strong> <em>Byte 17: </em><br/><em>Bit 4: Check “Daytime Running Light with dimmed Low Beam” (or “Daytime Running Light via Fog Lights,” depending on your version of VCDS)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/ab_975-e7b60077.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/veilleusejour3-c639151f.webp\"/></figure>\n<p><strong>8-</strong> Adjusting the fog light intensity (from 1% to 99%)</p>\n<p><em>Byte 20: </em><br/><em>Change the value in the Dec box</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/VagComByte20-adce5646.webp\"/></figure>"};
